userscript.function:

if (formObj) {
    formObj.unload();
}

formID = $sObject.formID = data.form_id;

var params = {
    FORM_ID: data.form_id,
    HOUSE_CODE: data.house_code
};

doServiceAjax('sepoa.svc.admin.AD_042_3', 'CONNECTION', 'doQueryFilterData', params, function(so) {
    if (so.status != 1) {
        Alert('Server Error');
        return;
    }

    var masterSF = new SepoaFormater(so.param.MASTER);
    var filterSF = new SepoaFormater(so.param.FILTER);
    var currentHouseCode = so.param.HOUSE_CODE;

    if (masterSF.getRowCount() == 0) {
        Alert('Data Not Found');
        return;
    }
    var masterFormJson = JSON.parse(masterSF.getValue("FORM_JSON", 0));

    var masterBlockArray = [];
    findBlockNode(masterFormJson, masterBlockArray, currentHouseCode);

    formObj = $sObject.formObj = new SepoaMultiDhtmlXFormObject(previewLayout, 'formObj', [masterFormJson], true);

    callFunction('AD_042_4', 'setData', [{FORM_ID: formID, HOUSE_CODE: currentHouseCode}, masterFormJson, masterBlockArray, filterSF.getArrayMap()]);
});


            var finder = ['block', 'fieldset'];

            for (var idx in data) {
                if (finder.indexOf(data[idx].type) + 1) {
                    if (data[idx].list) {
                        findBlockNode(data[idx].list, blockArray, houseCode);
                    }

					var orgType = data[idx].type;

                    if (data[idx].type != "block") {
                        var textData = Sepoa.cache.text.get(formID + '.' + data[idx].name);

                        if (textData.length > 0) {
                            if (textData.startsWith("Has not found text")) {
                                textData = "";
                            }
                        }

                        data[idx].label = data[idx].label || textData;
                    } else {
                        data[idx].type = "fieldset"
                        data[idx].label = "[block] " + data[idx].name || "";
                    }

                    if (data[idx].name) {
                        var obj = {};
                        obj.form_id = formID;
                        obj.name = data[idx].name;
                        obj.type = data[idx].type;
                        obj.org_type = orgType;
                        obj.visible = '0';
                        obj.label = data[idx].label;
                        obj.house_code = houseCode;
                        obj.tree_id = data[idx].name;
                        obj.tree_parent_id = '*';
                        obj.tree_value = data[idx].name;
                        obj.width = data[idx].width;
                        blockArray.push(obj);
                    }
                } else {
                    var text = Sepoa.cache.text.get(formID + '.' + data[idx].name);

                    data[idx].label = text;
                    if (data[idx].type == 'button') {
                        data[idx].value = text;
                    }
                }
            }


            // data == block, fieldset

            for (var idx in data) {
                var key = data[idx].key;
                var value = data[idx].value;

            	if(value.ITEM_TYPE == 'radio') {
            		var radioName = value.BLOCK_NAME.replace(/(.*)\{([0-9a-zA-Z_]{0,})\}/g, '$1');
            		var radioValue = value.BLOCK_NAME.replace(/(.*)\{([0-9a-zA-Z_]{0,})\}/g, '$2');
            		var radioItem = formObj._apiConnector('_getRGroup', [radioName, radioValue]);
            		if(value.VISIBLE == '1') { // 보이기
            			formObj.showItem(radioItem);
            		} else {
            			formObj.hideItem(radioItem);
            		}

            		if(value.REQUIRED == '1') { // 필수
            			formObj.setRequired(radioItem, true);
            		} else {
            			formObj.setRequired(radioItem, false);
            		}
            	} else {
            		if(value.VISIBLE == '1') { // 보이기
	                    formObj.showItem(key);
	                } else {
	                    formObj.hideItem(key);
	                }

	                if(value.ITEM_TYPE != 'label') {
	                	if(value.REQUIRED == '1') { // 필수
		                	formObj.setRequired(key, true);
		                } else {
		                	formObj.setRequired(key, false);
		                }
	                }
            	}

                var excludeTypeArray = ['button', 'label', 'checkbox']
                if(excludeTypeArray.indexOf(value.ITEM_TYPE) + 1) {
                	continue;
                }

                formObj.setItemWidth(key, value.INPUT_WIDTH);
            }


formObj.forEachObject(function(formID) {

    var form = formObj.getForm(formID);
    var selectNode = '';

    if(item.ITEM_TYPE == 'radio') {
    	var radioName = item.BLOCK_NAME.replace(/(.*)\{([0-9a-zA-Z_]{0,})\}/g, '$1');
    	var radioValue = item.BLOCK_NAME.replace(/(.*)\{([0-9a-zA-Z_]{0,})\}/g, '$2');
    	var rGroup = form._getRGroup(radioName, radioValue);
    	selectNode = form._getItemByName(rGroup);
    } else {
    	selectNode = form._getItemByName(item.BLOCK_NAME).children[0];
    }

    if (selectNode.classList.contains('dhxform_label')) {
        selectNode = selectNode.parentNode;
    }

    var recentNodes = document.getElementsByClassName('highlightItem');

    if (recentNodes.length > 0) {
        for (var idx in recentNodes) {
            if (recentNodes[idx].classList) {
                recentNodes[idx].classList.remove('highlightItem');
            }
        }
    }

    selectNode.classList.add('highlightItem');
})
